 import os
import re
import pandas as pd
import numpy as np

input_path = r"C:/Users/darpa/Downloads/Resume_Projects/AI Data Agent/data/etl_eval/input/payments_messy.csv"
output_dir = r"C:/Users/darpa/Downloads/Resume_Projects/AI Data Agent/data/etl_eval/output/h06"
os.makedirs(output_dir, exist_ok=True)

df = pd.read_csv(input_path)

def clean_amount(val):
    if pd.isna(val):
        return np.nan
    s = str(val)
    s = re.sub(r'[A-Za-z$,]', '', s)
    s = s.strip()
    if s == '':
        return np.nan
    try:
        return float(s)
    except ValueError:
        return np.nan

df['amount_cad'] = df['amount'].apply(clean_amount)

def parse_date(val):
    if pd.isna(val):
        return pd.NaT
    s = str(val).strip()
    if '/' in s:
        return pd.to_datetime(s, format='%m/%d/%Y', errors='coerce')
    else:
        return pd.to_datetime(s, errors='coerce')

df['paid_on'] = df['paid_on'].apply(parse_date)
df['paid_on'] = df['paid_on'].dt.strftime('%Y-%m-%d')

df.to_parquet(os.path.join(output_dir, "payments_cleaned.parquet"), index=False) 

